def list_boards(account_id, workspace_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_key(v):
        d = _parse_dt(v)
        return d if d is not None else datetime.datetime(1970, 1, 1)

    def _str_key(v):
        if v is None:
            return ""
        return str(v)

    def _encode_cursor(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii")

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    t0 = time.time()
    endpoint = "list_boards"
    log_file = _ensure_request_log()
    used_account_id = None
    status_code = "ok"

    try:
        if not isinstance(account_id, str) or not re.match(r"^mon_acct_[0-9A-Z]{18,}$", account_id):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        if workspace_id is not None:
            if not isinstance(workspace_id, str) or not re.match(r"^mon_wsp_[0-9A-Z]{18,}$", workspace_id):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
        if status is not None:
            if status not in ("active", "archived", "deleted"):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "name", "remote_updated_at"):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort")
        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Invalid order.", field="order")
        if cursor is not None and not isinstance(cursor, str):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        cur = None
        if cursor:
            cur = _decode_cursor(cursor)
            if not isinstance(cur, dict) or cur.get("v") != 1:
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            if cur.get("account_id") != account_id or cur.get("workspace_id") != workspace_id or cur.get("status") != status or cur.get("sort") != sort or cur.get("order") != order:
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Cursor does not match this query.", field="cursor")

        accounts = _load("monday_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
        if not acct:
            status_code = "UNAUTHORIZED"
            return _err("UNAUTHORIZED", "No active Monday account available for this request.")
        used_account_id = acct.get("id")

        workspaces = _load("workspaces.json")
        if workspace_id is not None:
            ws = next((w for w in workspaces if w.get("id") == workspace_id and w.get("account_id") == used_account_id), None)
            if ws is None:
                # Must not leak other account data; return empty
                resp = {
                    "data": [],
                    "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}
                }
                return resp

        boards = _load("boards.json")
        rows = [b for b in boards if b.get("account_id") == used_account_id and b.get("status") != "deleted"]
        if workspace_id is not None:
            rows = [b for b in rows if b.get("workspace_id") == workspace_id]
        if status is not None:
            rows = [b for b in rows if b.get("status") == status]

        total = len(rows)

        if sort in ("created_at", "updated_at", "remote_updated_at"):
            keyfn = lambda r: _dt_key(r.get(sort))
        else:
            keyfn = lambda r: _str_key(r.get(sort)).lower()

        reverse = (order == "desc")
        rows_sorted = sorted(rows, key=lambda r: (keyfn(r), _str_key(r.get("id"))), reverse=reverse)

        start = 0
        if cur:
            try:
                start = int(cur.get("offset", 0))
            except Exception:
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
            if start < 0 or start > len(rows_sorted):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Cursor offset out of range.", field="cursor")

        page = rows_sorted[start:start + limit]
        next_offset = start + len(page)
        has_more = next_offset < len(rows_sorted)
        next_cursor = None
        if has_more:
            next_cursor = _encode_cursor({
                "v": 1,
                "account_id": account_id,
                "workspace_id": workspace_id,
                "status": status,
                "sort": sort,
                "order": order,
                "offset": next_offset
            })

        return {
            "data": page,
            "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
        }
    finally:
        try:
            logs = _load(log_file)
            logs.append({
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "account_id": used_account_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso()
            })
            _save(log_file, logs)
        except Exception:
            pass

def get_board(board_id, **_extra):
