    t0 = time.time()
    endpoint = "get_board"
    log_file = _ensure_request_log()
    used_account_id = None
    status_code = "ok"

    try:
        if not isinstance(board_id, str) or not re.match(r"^mon_brd_[0-9A-Z]{18,}$", board_id):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")

        accounts = _load("monday_accounts.json")
        acct = next((a for a in accounts if a.get("status") == "active"), None)
        if not acct:
            status_code = "UNAUTHORIZED"
            return _err("UNAUTHORIZED", "No active Monday account available for this request.")
