            "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
        }
    finally:
        try:
            logs = _load(log_file)
            logs.append({
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "account_id": used_account_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": _now_iso()
            })
            _save(log_file, logs)
        except Exception:
            pass

