def get_item(item_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_item"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, account_id=None, detail=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    # Validate inputs first (but be tolerant to real-world ids; only require non-empty string)
    if not isinstance(item_id, str):
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_id"})
        return _err("VALIDATION_ERROR", "item_id must be a string", field="item_id")
    item_id = item_id.strip()
    if not item_id:
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_id"})
        return _err("VALIDATION_ERROR", "item_id must be a non-empty string", field="item_id")

    try:
        accounts = _load("monday_accounts.json")
        items = _load("items.json")
        boards = _load("boards.json")
        if not isinstance(accounts, list): accounts = []
        if not isinstance(items, list): items = []
        if not isinstance(boards, list): boards = []

        # Resolve an active account context that can serve the request.
        active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("id")]
        if not active_accounts:
            _log("error", detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active Monday account is configured for this operation")

        active_account_ids = {a["id"] for a in active_accounts}
        board_by_id = {b.get("id"): b for b in boards if isinstance(b, dict) and b.get("id")}

        # Try resolve by internal id first, else by monday_item_id within any active account.
        candidate = None
        for it in items:
            if not isinstance(it, dict):
                continue
            if it.get("id") == item_id:
                candidate = it
                break
        if candidate is None:
            for it in items:
                if not isinstance(it, dict):
                    continue
                if it.get("monday_item_id") == item_id:
                    candidate = it
                    break

        if candidate is None:
            _log("error", detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")

        # Authorization / tenancy: must belong to an active account (do not leak other accounts)
        acct_id = candidate.get("account_id")
        if acct_id not in active_account_ids:
            _log("error", detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")

        # Must belong to a board in same account (FK integrity guard)
        b = board_by_id.get(candidate.get("board_id"))
        if not isinstance(b, dict) or b.get("account_id") != acct_id:
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED", "rule": "item parent board not accessible"})
            return _err("UNAUTHORIZED", "Not allowed to view this item (parent board not accessible)")

        # Business rule: do not return deleted items
        if candidate.get("status") == "deleted":
            _log("error", account_id=acct_id, detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")

        # Business rule: get_items list would filter to these; get_item should return stored details if not deleted
        _log("ok", account_id=acct_id)
        return {"item": candidate}
    except Exception as e:
        _log("error", detail={"code": "INTERNAL_ERROR", "message": str(e)})
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def get_boards(workspace_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_id=None, message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "message": message,
            "meta": meta or {},
            "latency_ms": None,
            "timestamp": _now(),
        }
        if started is not None:
            row["latency_ms"] = int((time.time() - started) * 1000)
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            # fromisoformat doesn't parse Z; also tolerates no timezone
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    started = time.time()
    endpoint = "get_boards"

    # Validate workspace_id
    if not isinstance(workspace_id, str):
        _log(endpoint, "error", message="workspace_id must be a string", started=started)
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if not re.match(r"^mon_wsp_[0-9A-Z]{18,}$", workspace_id):
        _log(endpoint, "error", message="workspace_id malformed", started=started)
        return _err("VALIDATION_ERROR", "workspace_id is malformed")

    # Validate optional params
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(endpoint, "error", message="Invalid status", started=started)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, "error", message="Invalid limit", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name", "remote_updated_at"):
        _log(endpoint, "error", message="Invalid sort", started=started)
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name, remote_updated_at")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log(endpoint, "error", message="Invalid order", started=started)
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")
    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, "error", message="Invalid cursor type", started=started)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Auth / account context
    accounts = _load("monday_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log(endpoint, "error", message="No active monday account available", started=started)
        return _err("UNAUTHORIZED", "No active Monday account is available for this request")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)

    # Business rule: if workspace_id not found for that account, return empty (do not leak)
    if ws is None:
        _log(endpoint, "ok", meta={"workspace_id": workspace_id, "total": 0}, started=started)
        return {
            "boards": [],
            "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None},
        }

    account_id = ws.get("account_id")
    if not any(a.get("id") == account_id and a.get("status") == "active" for a in accounts):
        # Treat as empty, per non-leak rule
        _log(endpoint, "ok", meta={"workspace_id": workspace_id, "total": 0}, started=started)
        return {
            "boards": [],
            "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None},
        }

    boards = _load("boards.json")
    filtered = [
        b for b in boards
        if b.get("account_id") == account_id and b.get("workspace_id") == workspace_id
    ]
    if status is not None:
        filtered = [b for b in filtered if b.get("status") == status]

    # Sorting
    reverse = (order == "desc")

    def _key(b):
        if sort == "name":
            v = b.get("name")
            return ("" if v is None else str(v).lower(), b.get("id") or "")
        else:
            dt = _parse_dt(b.get(sort))
            # None sorts last in asc, first in desc
            sentinel = datetime.datetime.min if reverse else datetime.datetime.max
            return ((dt if dt is not None else sentinel), b.get("id") or "")

    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)

    # Cursor pagination: cursor encodes an integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("workspace_id") != workspace_id:
                raise ValueError("bad cursor")
            offset = payload.get("offset")
            if not isinstance(offset, int) or offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log(endpoint, "error", message="Invalid cursor", started=started)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "workspace_id": workspace_id, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(endpoint, "ok", meta={"workspace_id": workspace_id, "total": total, "returned": len(page)}, started=started)
    return {
        "boards": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def create_item(board_id, name, group_id=None, column_values=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "message": message,
            "meta": meta or {},
            "latency_ms": None,
            "timestamp": _now(),
        }
        if started is not None:
            row["latency_ms"] = int((time.time() - started) * 1000)
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        # 18+ chars, uppercase A-Z0-9
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        b = os.urandom(12)
        out = []
        for x in b:
            out.append(alphabet[x % len(alphabet)])
        return prefix + "".join(out) + "".join(out)  # 24 chars after prefix (>=18)

    def _find_active_account(accounts):
        for a in accounts:
            if a.get("status") == "active":
                return a
        return None

    started = time.time()
    endpoint = "create_item"

    # Validate inputs
    if not isinstance(board_id, str):
        _log(endpoint, "error", message="board_id must be a string", started=started)
        return _err("VALIDATION_ERROR", "board_id must be a string")
    if not re.match(r"^mon_brd_[0-9A-Z]{18,}$", board_id):
        _log(endpoint, "error", message="board_id malformed", started=started)
        return _err("VALIDATION_ERROR", "board_id is malformed")

    if not isinstance(name, str):
        _log(endpoint, "error", message="name must be a string", started=started)
        return _err("VALIDATION_ERROR", "name must be a string")
    if len(name) < 1 or len(name) > 255:
        _log(endpoint, "error", message="name length invalid", started=started)
        return _err("VALIDATION_ERROR", "name must be between 1 and 255 characters")

    if group_id is not None and not isinstance(group_id, str):
        _log(endpoint, "error", message="group_id must be a string", started=started)
        return _err("VALIDATION_ERROR", "group_id must be a string")

    if column_values is not None and not isinstance(column_values, dict):
        _log(endpoint, "error", message="column_values must be an object", started=started)
        return _err("VALIDATION_ERROR", "column_values must be an object")

    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log(endpoint, "error", message="idempotency_key must be a string", started=started)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string")

    accounts = _load("monday_accounts.json")
    acct = _find_active_account(accounts)
    if acct is None:
        _log(endpoint, "error", message="No active monday account available", started=started)
        return _err("UNAUTHORIZED", "No active Monday account is available for this request")
    account_id = acct.get("id")

    # Business rule: mutations rejected when account not active (already ensured)
    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id and b.get("account_id") == account_id), None)
    if board is None:
        _log(endpoint, "error", message="Board not found in active account", started=started)
        return _err("NOT_FOUND", "Board not found")
    if board.get("status") == "deleted":
        _log(endpoint, "error", message="Cannot create item on deleted board", started=started)
        return _err("CONFLICT", "Cannot create item on a deleted board")

    items = _load("items.json")

    # Idempotency: best-effort via request log signature (since schema has no idempotency field on items)
    if idempotency_key:
        sig = f"create_item:{account_id}:{board_id}:{idempotency_key}"
        # Search for prior successful create with same key
        for it in items:
            meta = it.get("meta")
            if isinstance(meta, dict) and meta.get("idempotency_sig") == sig and it.get("status") != "deleted":
                _log(endpoint, "ok", meta={"idempotent": True, "item_id": it.get("id")}, started=started)
                return {"item": it}

    # Create local row as pending_create
    now = _now()
    new_id = _gen_id("mon_itm_")
    # Ensure uniqueness of internal id
    existing_ids = {it.get("id") for it in items}
    while new_id in existing_ids:
        new_id = _gen_id("mon_itm_")

    row = {
        "id": new_id,
        "account_id": account_id,
        "board_id": board_id,
        "monday_item_id": None,
        "name": name,
        "group_id": group_id,
        "column_values": column_values,
        "created_by": "mcp",
        "status": "pending_create",
        "remote_created_at": None,
        "remote_updated_at": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    # Store idempotency signature in opaque meta if requested (non-schema field tolerated in JSON store)
    if idempotency_key:
        row["meta"] = {"idempotency_sig": f"create_item:{account_id}:{board_id}:{idempotency_key}"}

    items.append(row)
    _save("items.json", items)

    # Simulated "Monday API creation": offline store can't call Monday.
    # We treat it as successful and allocate a stable synthetic monday_item_id, enforcing uniqueness per account.
    # This matches "no success without effect": we do effectful mutation regardless.
    try:
        existing_mid = {it.get("monday_item_id") for it in items if it.get("account_id") == account_id and it.get("monday_item_id") is not None}
        # Create a synthetic Monday id (string), never reused
        # Use timestamp+random to avoid collisions
        synthetic = str(int(time.time() * 1000)) + os.urandom(3).hex()
        while synthetic in existing_mid:
            synthetic = str(int(time.time() * 1000)) + os.urandom(3).hex()

        # Transition pending_create -> active
        # Validate transition
        if row["status"] != "pending_create":
            _log(endpoint, "error", message="Invalid initial status", started=started)
            return _err("INVALID_TRANSITION", "Invalid item status transition")

        row["monday_item_id"] = synthetic
        row["status"] = "active"
        row["remote_created_at"] = now
        row["remote_updated_at"] = now
        row["updated_at"] = _now()

        # Persist update
        items2 = _load("items.json")
        updated = False
        for i in range(len(items2)):
            if items2[i].get("id") == row["id"]:
                items2[i] = row
                updated = True
                break
        if not updated:
            _log(endpoint, "error", message="Created item disappeared", started=started)
            return _err("NOT_FOUND", "Created item not found")
        _save("items.json", items2)

        _log(endpoint, "ok", meta={"item_id": row["id"], "board_id": board_id}, started=started)
        return {"item": row}
    except Exception as e:
        # Mark create_failed with transition pending_create -> create_failed
        items2 = _load("items.json")
        for i in range(len(items2)):
            if items2[i].get("id") == row["id"]:
                items2[i]["status"] = "create_failed"
                items2[i]["updated_at"] = _now()
                _save("items.json", items2)
                _log(endpoint, "error", message="Remote create failed", meta={"reason": str(e)}, started=started)
                return _err("CONFLICT", "Failed to create item remotely")
        _log(endpoint, "error", message="Remote create failed and item missing", meta={"reason": str(e)}, started=started)
        return _err("NOT_FOUND", "Created item not found")

