        })
        _save("request_logs.json", logs)

    if not isinstance(item_id, str):
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_id"})
        return _err("VALIDATION_ERROR", "item_id must be a string", field="item_id")
    item_id = item_id.strip()
    if not item_id:
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_id"})
        return _err("VALIDATION_ERROR", "item_id must be a non-empty string", field="item_id")

    try:
        accounts = _load("monday_accounts.json")
        items = _load("items.json")
        boards = _load("boards.json")
        if not isinstance(accounts, list): accounts = []
        if not isinstance(items, list): items = []
        if not isinstance(boards, list): boards = []

        active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("id")]
        if not active_accounts:
            _log("error", detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active Monday account is configured for this operation")

        active_account_ids = {a["id"] for a in active_accounts}
        board_by_id = {b.get("id"): b for b in boards if isinstance(b, dict) and b.get("id")}

        # Resolve item by internal id first, else by monday_item_id within any active account.
        idx = None
        it = None
        for i, row in enumerate(items):
            if isinstance(row, dict) and row.get("id") == item_id:
                idx, it = i, row
                break
        if it is None:
            for i, row in enumerate(items):
                if isinstance(row, dict) and row.get("monday_item_id") == item_id:
                    idx, it = i, row
                    break

        if it is None:
            _log("error", detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")

        acct_id = it.get("account_id")
        if acct_id not in active_account_ids:
            _log("error", detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Item not found")

        # Mutations must be rejected when account not active (already ensured by acct_id in active_account_ids)
        b = board_by_id.get(it.get("board_id"))
        if not isinstance(b, dict) or b.get("account_id") != acct_id:
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED", "rule": "item parent board not accessible"})
            return _err("UNAUTHORIZED", "Not allowed to delete this item (parent board not accessible)")

        # Conflict if already deleted
        if it.get("status") == "deleted":
            _log("error", account_id=acct_id, detail={"code": "CONFLICT", "rule": "already deleted"})
            return _err("CONFLICT", "Item is already deleted")

        # Enforce lifecycle transitions for items: only pending_create/create_failed/active -> deleted
        cur = it.get("status")
        allowed = {"pending_create", "create_failed", "active"}
        if cur not in allowed:
            _log("error", account_id=acct_id, detail={"code": "INVALID_TRANSITION", "from": cur, "to": "deleted"})
            return _err("INVALID_TRANSITION", f"Cannot transition item from '{cur}' to 'deleted'")

        # Soft delete + audit timestamps
        now = _now()
        new_it = dict(it)
        new_it["status"] = "deleted"
        new_it["deleted_at"] = now
        new_it["updated_at"] = now
        # Never reuse monday_item_id; we retain as-is

        items[idx] = new_it
        _save("items.json", items)

        _log("ok", account_id=acct_id)
        return {"item": new_it}
    except Exception as e:
        _log("error", detail={"code": "INTERNAL_ERROR", "message": str(e)})
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def create_item_with_demo(account_id, board_id, name, group_id=None, demo_mode=None, demo_column_ids=None, column_values=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, random, string, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_item_with_demo"
    logs_name = "request_logs.json"
    accounts_name = "monday_accounts.json"
    boards_name = "boards.json"
    items_name = "items.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, account_id=None, detail=None, credential_id=None):
        logs = _load(logs_name)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%dT%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "detail": detail
        })
        _save(logs_name, logs)

    def _gen_id(prefix):
        # 18+ chars uppercase base32-ish
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(22))

    def _is_obj(x):
        return isinstance(x, dict)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^mon_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "account_id"})
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not isinstance(board_id, str) or not re.match(r"^mon_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
    if not isinstance(name, str) or not (1 <= len(name) <= 255):
        _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string of length 1..255", field="name")
    if group_id is not None and not isinstance(group_id, str):
        _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "group_id"})
        return _err("VALIDATION_ERROR", "group_id must be a string", field="group_id")
    if demo_mode is None:
        demo_mode = "none"
    if not isinstance(demo_mode, str) or demo_mode not in ("none", "all_columns", "selected_columns"):
        _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "demo_mode"})
        return _err("VALIDATION_ERROR", "demo_mode must be one of: none, all_columns, selected_columns", field="demo_mode")
    if demo_mode == "selected_columns":
        if not isinstance(demo_column_ids, list) or len(demo_column_ids) < 1 or any(not isinstance(x, str) or not x for x in demo_column_ids):
            _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "demo_column_ids"})
            return _err("VALIDATION_ERROR", "demo_column_ids must be a non-empty array of strings when demo_mode='selected_columns'", field="demo_column_ids")
    else:
        if demo_column_ids is not None:
            _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "demo_column_ids"})
            return _err("VALIDATION_ERROR", "demo_column_ids must be null unless demo_mode='selected_columns'", field="demo_column_ids")
    if column_values is not None and not _is_obj(column_values):
        _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "column_values"})
        return _err("VALIDATION_ERROR", "column_values must be an object", field="column_values")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log("error", account_id=account_id, detail={"code": "VALIDATION_ERROR", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")

    accounts = _load(accounts_name)
    account = next((a for a in accounts if a.get("id") == account_id), None)
    if not account:
        _log("error", detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No accessible Monday account for this request")
    if account.get("status") != "active":
        _log("error", account_id=account_id, detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Account is not active")

    boards = _load(boards_name)
    board = next((b for b in boards if b.get("id") == board_id and b.get("account_id") == account_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", account_id=account_id, detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Board not found")

    items = _load(items_name)

    # Idempotency: if provided, return existing active/pending/create_failed item created with that key
    # Stored via column_values.__idempotency_key (opaque but stable) to avoid schema changes.
    if idempotency_key is not None:
        for it in items:
            if it.get("account_id") == account_id and it.get("board_id") == board_id and it.get("status") != "deleted":
                cv = it.get("column_values") if isinstance(it.get("column_values"), dict) else {}
                if cv.get("__idempotency_key") == idempotency_key:
                    _log("ok", account_id=account_id, detail={"idempotent": True})
                    return {"item": it, "idempotent": True}

    def _demo_for_columns(col_ids):
        # Generate simple deterministic-ish demo payloads; treated as opaque by rest of system.
        demo = {}
        for cid in col_ids:
            # produce varied types as strings to keep opaque
            demo[cid] = {
                "text": "Demo " + "".join(random.choice(string.ascii_letters) for _ in range(8)),
                "number": random.randint(1, 1000),
                "date": datetime.date.today().isoformat()
            }
        return demo

    explicit = copy.deepcopy(column_values) if isinstance(column_values, dict) else {}
    demo_payload = {}
    if demo_mode == "all_columns":
        # Without board schema/columns cache, cannot enumerate columns; generate a minimal sentinel demo payload.
        demo_payload = {"__demo": {"enabled": True, "mode": "all_columns", "generated_at": _now()}}
    elif demo_mode == "selected_columns":
        demo_payload = _demo_for_columns(demo_column_ids)

    merged = {}
    # Demo first, then explicit overrides
    if isinstance(demo_payload, dict):
        merged.update(demo_payload)
    if isinstance(explicit, dict):
        merged.update(explicit)
    if idempotency_key is not None:
        merged["__idempotency_key"] = idempotency_key

    now = _now()
    new_item = {
        "id": _gen_id("mon_itm"),
        "account_id": account_id,
        "board_id": board_id,
        "monday_item_id": None,
        "name": name,
        "group_id": group_id,
        "column_values": merged if merged else None,
        "created_by": "mcp",
        "status": "pending_create",
        "remote_created_at": None,
        "remote_updated_at": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }
    items.append(new_item)
    _save(items_name, items)

    # Simulated remote Monday API creation:
    # If account is active, treat as success. (No actual network available.)
    try:
        remote_id = "md_itm_" + "".join(random.choice("0123456789") for _ in range(10))
        # Enforce uniqueness(account_id, monday_item_id) where not null
        for it in items:
            if it.get("account_id") == account_id and it.get("monday_item_id") == remote_id:
                remote_id = "md_itm_" + "".join(random.choice("0123456789") for _ in range(10))
                break

        now2 = _now()
        # Update in-place
        new_item["monday_item_id"] = remote_id
        new_item["status"] = "active"
        new_item["remote_created_at"] = now2
        new_item["remote_updated_at"] = now2
        new_item["updated_at"] = now2
        _save(items_name, items)
        _log("ok", account_id=account_id)
        return {"item": new_item}
    except Exception:
        # unexpected: mark create_failed but do not raise
        now3 = _now()
        new_item["status"] = "create_failed"
        new_item["remote_updated_at"] = now3
        new_item["updated_at"] = now3
        _save(items_name, items)
        _log("error", account_id=account_id, detail={"code": "CONFLICT", "remote": "create_failed"})
        return {"item": new_item}

