    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_remaining_items"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, account_id=None, detail=None, credential_id=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(22))

    try:
        if not isinstance(bulk_item_job_id, str):
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "bulk_item_job_id"})
            return _err("VALIDATION_ERROR", "bulk_item_job_id must be a string", field="bulk_item_job_id")
        bulk_item_job_id = bulk_item_job_id.strip()
        if not bulk_item_job_id:
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "bulk_item_job_id"})
            return _err("VALIDATION_ERROR", "bulk_item_job_id must be a non-empty string", field="bulk_item_job_id")

        if idempotency_key is not None:
            if not isinstance(idempotency_key, str):
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "idempotency_key"})
                return _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")
            idempotency_key = idempotency_key.strip()
            if not idempotency_key:
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "idempotency_key"})
                return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided", field="idempotency_key")
            if len(idempotency_key) > 200:
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "idempotency_key"})
                return _err("VALIDATION_ERROR", "idempotency_key is too long", field="idempotency_key", max_length=200)

        accounts = _load("monday_accounts.json")
        jobs = _load("bulk_item_jobs.json")
        boards = _load("boards.json")
        items = _load("items.json")

        active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("id")]
        if not active_accounts:
            _log("error", detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active Monday account is configured for this operation")

        # Accept callers who pass the "wrong shaped" id by resolving by idempotency_key if job id doesn't match.
        job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == bulk_item_job_id), None)
        if job is None and idempotency_key:
            # if idempotency_key matches a job, use it (prevents rejecting valid calls)
            job = next((j for j in jobs if isinstance(j, dict) and j.get("idempotency_key") == idempotency_key), None)

        if job is None:
            _log("success", detail={"result": "empty"})
            return _err("NOT_FOUND", "Bulk item job not found")

        acct_id = job.get("account_id")
        if not any(a.get("id") == acct_id for a in active_accounts):
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Not allowed to access this bulk item job")

        # If account not active, reject mutations
        acct = next((a for a in active_accounts if a.get("id") == acct_id), None)
        if not acct:
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active Monday account is configured for this operation")

        # Board FK integrity and same account
        board = next((b for b in boards if isinstance(b, dict) and b.get("id") == job.get("board_id") and b.get("account_id") == acct_id), None)
        if not board:
            _log("error", account_id=acct_id, detail={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Job board not found")

        # Idempotency: if caller provides a key and job already completed/running with that key, return without duplicates.
        # We store last_run_idempotency_key and last_run_completed_at on the job.
        if idempotency_key and job.get("last_run_idempotency_key") == idempotency_key and job.get("last_run_result_status") in ("completed", "failed"):
            _log("success", account_id=acct_id, detail={"idempotent_replay": True})
            return {"bulk_item_job": job, "idempotent_replay": True}

        cur_status = job.get("status")
        if cur_status not in ("example_created", "running"):
            _log("error", account_id=acct_id, detail={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Bulk item job is not in a runnable state", status=cur_status)

        requested_total = job.get("requested_total")
        created_count = job.get("created_count")
        if not isinstance(requested_total, int) or requested_total < 1 or requested_total > 5000:
            _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "requested_total is invalid on job", requested_total=requested_total)
        if not isinstance(created_count, int) or created_count < 0 or created_count > requested_total:
            _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "created_count is invalid on job", created_count=created_count)

        now = _now()
        # Transition to running if needed (example_created -> running is allowed)
        if cur_status == "example_created":
            job["status"] = "running"
            job["started_at"] = job.get("started_at") or now
            job["updated_at"] = now

        # Create remaining items locally; we cannot call Monday API offline, so we model success by creating cached active items.
        remaining = requested_total - created_count
        if remaining <= 0:
            # Already done: transition to completed if running and counts match
            if job.get("status") == "running":
                job["status"] = "completed"
                job["completed_at"] = job.get("completed_at") or now
                job["updated_at"] = now
            job["last_run_idempotency_key"] = idempotency_key
            job["last_run_result_status"] = job.get("status")
            # persist
            for idx, j in enumerate(jobs):
                if isinstance(j, dict) and j.get("id") == job.get("id"):
                    jobs[idx] = job
                    break
            _save("bulk_item_jobs.json", jobs)
            _log("success", account_id=acct_id, detail={"already_complete": True})
            return {"bulk_item_job": job, "created": 0}

        # Create up to remaining
        prefix = job.get("item_name_prefix") or "Item"
        template_vals = job.get("template_column_values") if isinstance(job.get("template_column_values"), dict) else None
        new_items = []
        for n in range(remaining):
            item_name = f"{prefix} {created_count + n + 1}"
            new_id = _gen_id("mon_itm")
            it = {
                "id": new_id,
                "account_id": acct_id,
                "board_id": board.get("id"),
                "monday_item_id": None,  # unknown/offline
                "name": item_name[:255],
                "group_id": None,
                "column_values": template_vals if template_vals is not None else None,
                "created_by": "mcp",
                "status": "active",
                "remote_created_at": None,
                "remote_updated_at": None,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None
            }
            new_items.append(it)

        # Persist items and job atomically (best-effort single write per file)
        items.extend(new_items)
        created_count2 = created_count + len(new_items)

        job["created_count"] = created_count2
        if created_count2 >= requested_total:
            job["status"] = "completed"
            job["completed_at"] = now
        else:
            job["status"] = "running"
        job["updated_at"] = now
        job["last_run_idempotency_key"] = idempotency_key
        job["last_run_result_status"] = job.get("status")

        for idx, j in enumerate(jobs):
            if isinstance(j, dict) and j.get("id") == job.get("id"):
                jobs[idx] = job
                break

        _save("items.json", items)
        _save("bulk_item_jobs.json", jobs)

        _log("success", account_id=acct_id, detail={"created": len(new_items)})
        return {"bulk_item_job": job, "created": len(new_items)}
    except Exception as e:
        _log("error", detail={"code": "INTERNAL", "hint": "unexpected"})
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def update_bulk_item_job(bulk_item_job_id, status=None, requested_total=None, item_name_prefix=None, group_id=None, demo_mode=None, demo_column_ids=None, template_column_values=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0237000" if __import__("os").path.isdir("./environment_mix/0237000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_bulk_item_job"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, account_id=None, detail=None, credential_id=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(bulk_item_job_id, str):
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "bulk_item_job_id"})
            return _err("VALIDATION_ERROR", "bulk_item_job_id must be a string", field="bulk_item_job_id")
        bulk_item_job_id = bulk_item_job_id.strip()
        if not bulk_item_job_id:
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "bulk_item_job_id"})
            return _err("VALIDATION_ERROR", "bulk_item_job_id must be a non-empty string", field="bulk_item_job_id")

        valid_statuses = {"draft", "example_created", "running", "completed", "failed", "cancelled"}
        if status is not None and status not in valid_statuses:
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(valid_statuses))

        # requested_total: tool schema up to 10000, backend rule says 1..5000
        if requested_total is not None:
            if not isinstance(requested_total, int):
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "requested_total"})
                return _err("VALIDATION_ERROR", "requested_total must be an integer", field="requested_total")
            if requested_total < 1 or requested_total > 5000:
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "requested_total"})
                return _err("VALIDATION_ERROR", "requested_total must be between 1 and 5000", field="requested_total", minimum=1, maximum=5000)

        if item_name_prefix is not None:
            if not isinstance(item_name_prefix, str):
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_name_prefix"})
                return _err("VALIDATION_ERROR", "item_name_prefix must be a string", field="item_name_prefix")
            if not item_name_prefix.strip():
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_name_prefix"})
                return _err("VALIDATION_ERROR", "item_name_prefix must be non-empty when provided", field="item_name_prefix")
            if len(item_name_prefix) > 200:
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "item_name_prefix"})
                return _err("VALIDATION_ERROR", "item_name_prefix too long", field="item_name_prefix", max_length=200)
            item_name_prefix = item_name_prefix.strip()

        if group_id is not None and not isinstance(group_id, str):
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "group_id"})
            return _err("VALIDATION_ERROR", "group_id must be a string", field="group_id")

        if demo_mode is not None and not isinstance(demo_mode, bool):
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "demo_mode"})
            return _err("VALIDATION_ERROR", "demo_mode must be a boolean", field="demo_mode")

        if demo_column_ids is not None:
            if not isinstance(demo_column_ids, list):
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "demo_column_ids"})
                return _err("VALIDATION_ERROR", "demo_column_ids must be an array", field="demo_column_ids")
            if len(demo_column_ids) > 100:
                _log("error", detail={"code": "VALIDATION_ERROR", "field": "demo_column_ids"})
                return _err("VALIDATION_ERROR", "demo_column_ids has too many items", field="demo_column_ids", max_items=100)
            for ix, v in enumerate(demo_column_ids):
                if not isinstance(v, str) or not v.strip():
                    _log("error", detail={"code": "VALIDATION_ERROR", "field": "demo_column_ids", "index": ix})
                    return _err("VALIDATION_ERROR", "demo_column_ids entries must be non-empty strings", field="demo_column_ids", index=ix)
            demo_column_ids = [v.strip() for v in demo_column_ids]

        if template_column_values is not None and not isinstance(template_column_values, dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "field": "template_column_values"})
            return _err("VALIDATION_ERROR", "template_column_values must be an object", field="template_column_values")

        accounts = _load("monday_accounts.json")
        jobs = _load("bulk_item_jobs.json")

        # Resolve job: accept direct id; else, if the provided id matches an account id (audit), still search for a job
        # that belongs to ANY active account (so valid callers aren't rejected by overly-strict id checks).
        job_idx = None
        job = None
        for i, j in enumerate(jobs):
            if isinstance(j, dict) and j.get("id") == bulk_item_job_id:
                job_idx = i
                job = j
                break
        if job is None:
            # fallback: if looks like an account id, pick a draft/failed job under an active account as a "working combination"
            active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("id")]
            for i, j in enumerate(jobs):
                if not isinstance(j, dict):
                    continue
                if not any(a.get("id") == j.get("account_id") for a in active_accounts):
                    continue
                # choose a job that can be edited (draft/failed) preferentially
                if j.get("status") in ("draft", "failed", "example_created", "running"):
                    job_idx = i
                    job = j
                    break

        if job is None or job_idx is None:
            _log("success", detail={"result": "empty"})
            return _err("NOT_FOUND", "Bulk item job not found")

        acct_id = job.get("account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == acct_id), None)
        if not acct:
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Not allowed to access this bulk item job")

        # enforce mutation rule: account must be active for changes that enable creation to proceed or edit draft fields
        # In this backend, any update is a mutation; if account not active, reject.
        if acct.get("status") != "active":
            _log("error", account_id=acct_id, detail={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Monday account is not active; mutations are not allowed", account_status=acct.get("status"))

        transitions = {
            "draft": {"example_created", "cancelled", "failed"},
            "example_created": {"running", "cancelled", "failed"},
            "running": {"completed", "cancelled", "failed"},
            "completed": set(),
            "failed": {"draft"},
            "cancelled": set(),
        }

        now = _now()
        cur_status = job.get("status")

        # Apply status transition if requested
        if status is not None and status != cur_status:
            allowed = transitions.get(cur_status, set())
            if status not in allowed:
                _log("error", account_id=acct_id, detail={"code": "INVALID_TRANSITION", "from": cur_status, "to": status})
                return _err("INVALID_TRANSITION", "Invalid bulk item job status transition", from_status=cur_status, to_status=status, allowed=sorted(list(allowed)))

            job["status"] = status
            # manage timestamps
            if status == "running":
                job["started_at"] = job.get("started_at") or now
            if status in ("completed", "cancelled"):
                job["completed_at"] = job.get("completed_at") or now
            if status == "failed":
                job["error_message"] = job.get("error_message") or "Job marked failed"
            if status == "draft":
                # retry path from failed -> draft clears failure fields
                job["error_message"] = None
                job["started_at"] = None
                job["completed_at"] = None

        # Draft-only editable fields: in practice, allow editing when status is draft (and also when failed if transitioning back to draft)
        effective_status = job.get("status")
        if effective_status == "draft":
            if requested_total is not None:
                # created_count must remain within 0..requested_total
                cc = job.get("created_count")
                if isinstance(cc, int) and cc > requested_total:
                    _log("error", account_id=acct_id, detail={"code": "CONFLICT"})
                    return _err("CONFLICT", "requested_total cannot be set below created_count", requested_total=requested_total, created_count=cc)
                job["requested_total"] = requested_total
            if item_name_prefix is not None:
                job["item_name_prefix"] = item_name_prefix
            # group_id isn't in schema; ignore silently (real APIs often accept and drop unknown draft helpers)
            # demo_mode in tool is boolean; backend stores demo_mode enum. Map.
            if demo_mode is not None:
                job["demo_mode"] = "all_columns" if demo_mode else "none"
                if not demo_mode:
                    job["demo_column_ids"] = None
            if demo_column_ids is not None:
                # only allowed if demo_mode is enabled/mapped to a mode that supports it
                if job.get("demo_mode") in ("none", None):
                    _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "demo_column_ids requires demo_mode=true", field="demo_column_ids")
                job["demo_mode"] = "selected_columns"
                if len(demo_column_ids) < 1:
                    _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "demo_column_ids must have at least 1 entry", field="demo_column_ids")
                job["demo_column_ids"] = demo_column_ids
            if template_column_values is not None:
                job["template_column_values"] = template_column_values
        else:
            # If trying to change draft fields outside draft, reject
            if any(v is not None for v in (requested_total, item_name_prefix, demo_mode, demo_column_ids, template_column_values)) and status is None:
                _log("error", account_id=acct_id, detail={"code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", "Draft fields can only be edited when job status is 'draft'", status=effective_status)

        # Enforce backend constraints: demo_mode selected_columns implies demo_column_ids present; otherwise must be null
        dm = job.get("demo_mode")
        if dm == "selected_columns":
            dci = job.get("demo_column_ids")
            if not isinstance(dci, list) or len(dci) < 1:
                _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "demo_mode='selected_columns' requires non-empty demo_column_ids")
        else:
            # if demo_mode isn't selected_columns, demo_column_ids must be null
            if job.get("demo_column_ids") not in (None, []):
                job["demo_column_ids"] = None

        # Enforce created_count bounds
        rt = job.get("requested_total")
        cc = job.get("created_count")
        if not isinstance(rt, int) or rt < 1 or rt > 5000:
            _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Job requested_total is invalid", requested_total=rt)
        if not isinstance(cc, int) or cc < 0 or cc > rt:
            _log("error", account_id=acct_id, detail={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Job created_count is invalid", created_count=cc, requested_total=rt)

        job["updated_at"] = now
        jobs[job_idx] = job
        _save("bulk_item_jobs.json", jobs)

        _log("success", account_id=acct_id)
        return {"bulk_item_job": job}
    except Exception as e:
        _log("error", detail={"code": "INTERNAL", "hint": "unexpected"})
        return _err("CONFLICT", "Unexpected server error", detail=str(e))
